func TestClearTokensClearsPersistedAPIKeyAuth(t *testing.T) {
	cfg := &Config{
		Path:           filepath.Join(t.TempDir(), "config.toml"),
		AuthHeaderVal:  "legacy-header",
		AccessToken:    "access-token",
		RefreshToken:   "refresh-token",
		TokenExpiry:    time.Now().Add(time.Hour),
		ClientID:       "client-id",
		ClientSecret:   "client-secret",
		MondayApiToken: "api-token",
	}
	if err := cfg.ClearTokens(); err != nil {
		t.Fatalf("ClearTokens() error = %v", err)
	}

	loaded, err := Load(cfg.Path)
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	if got := loaded.AuthHeader(); got != "" {
		t.Fatalf("AuthHeader() after logout = %q, want empty", got)
	}
	if loaded.AuthHeaderVal != "" || loaded.AccessToken != "" || loaded.RefreshToken != "" || loaded.MondayApiToken != "" {
		t.Fatalf("stored auth fields not cleared: %+v", loaded)
	}
	if loaded.ClientID != "" || loaded.ClientSecret != "" {
		t.Fatalf("client credentials not cleared: id=%q secret=%q", loaded.ClientID, loaded.ClientSecret)
	}
	if !loaded.TokenExpiry.IsZero() {
		t.Fatalf("TokenExpiry after logout = %s, want zero", loaded.TokenExpiry)
	}
}
